import os
import requests

def paginate():
    cursor = ""
    while True:
        resp = requests.get(
            "https://api.twitterapis.com/twitter/article/list",
            headers={"Authorization": f"Bearer {os.environ['TWITTERAPIS_KEY']}"},
            params={"lifecycle": "draft", "cursor": cursor},
        )
        resp.raise_for_status()
        data = resp.json()
        items = data.get("articles", [])
        if not items:
            break
        for item in items:
            yield item
        cursor = data.get("next_cursor")
        if not cursor:
            break

for item in paginate():
    print(item)

