const URL = "https://api.twitterapis.com/twitter/grok/chat";
const headers = {
  Authorization: `Bearer ${process.env.TWITTERAPIS_KEY}`,
  "Content-Type": "application/json",
};

const first = await (
  await fetch(URL, {
    method: "POST",
    headers,
    body: JSON.stringify({ message: "What are people on X saying about the WWDC keynote today?" }),
  })
).json();

// Nothing is stored on our side, so you carry the history forward yourself.
const second = await (
  await fetch(URL, {
    method: "POST",
    headers,
    body: JSON.stringify({
      conversation_id: first.conversation_id,
      messages: [
        { role: "user", content: "What are people on X saying about the WWDC keynote today?" },
        {
          role: "assistant",
          content: first.answer,
          response_id: first.response_id,
          parent_response_id: first.user_response_id,
        },
      ],
      message: "Which developer accounts are driving that?",
    }),
  })
).json();

console.log(second.answer);

